`)}function sg(e){const t=kI(e);if(!t)return"未知框架。可用："+Vi.map(i=>i.id).join(", ");const n=EI[t.id]||{},r=(i,a)=>Array.isArray(a)&&a.length?["- "+i+": "+a.join("；")]:[];return["## "+t.name+" ("+t.id+")","- 领域: "+t.domains.join("/"),"- 用途: "+t.purpose,"- 适用: "+t.use_when.join("；"),"- 不适用: "+t.avoid_when.join("；"),...r("必需输入",n.required_inputs),...r("执行步骤",n.steps),...r("输出契约",n.output_contract),...r("常见错误",n.common_mistakes),...r("评审标准",n.review_rubric),"- 关联: "+t.related.join("；")].join(`
